CREATE OR REPLACE FUNCTION public.cancel_ride(p_ride_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_prev  text;
  v_seats integer;
  v_hist_reason text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  BEGIN
    SELECT r.status
      INTO STRICT v_prev
      FROM public.rides r
     WHERE r.ride_id = p_ride_id
       FOR UPDATE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE EXCEPTION 'El viaje no existe';
  END;

  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Solo el conductor puede cancelar el viaje';
  END IF;

  IF v_prev = 'cancelled' THEN
    RETURN;
  END IF;

  PERFORM public.validate_ride_transition(v_prev, 'cancelled');

  SELECT COALESCE(SUM(b.seats_reserved), 0)::integer
    INTO v_seats
    FROM public.bookings b
   WHERE b.ride_id = p_ride_id
     AND b.status = 'confirmed';

  UPDATE public.bookings b
     SET status = 'cancelled'
   WHERE b.ride_id = p_ride_id
     AND b.status IN ('pending', 'confirmed');

  UPDATE public.rides r
     SET status = 'cancelled',
         available_seats = r.available_seats + v_seats
   WHERE r.ride_id = p_ride_id;

  UPDATE public.chats c
     SET closed_at = timezone('utc', now())
   WHERE c.ride_id = p_ride_id
     AND c.closed_at IS NULL;

  v_hist_reason
    := COALESCE(
       NULLIF(btrim(COALESCE(p_reason, '')), ''),
       'ride_cancelled_by_driver'
     );

  INSERT INTO public.ride_status_history (
    ride_id,
    status,
    previous_status,
    actor_id,
    reason
  )
  VALUES (
    p_ride_id,
    'cancelled',
    v_prev,
    v_actor,
    v_hist_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_ride(p_ride_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_prev  text;
  v_remaining integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  -- Lock the ride row
  BEGIN
    SELECT r.status
      INTO STRICT v_prev
      FROM public.rides r
     WHERE r.ride_id = p_ride_id
       FOR UPDATE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE EXCEPTION 'El viaje no existe';
  END;

  -- Only driver can complete
  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Solo el conductor puede finalizar el viaje';
  END IF;

  -- Idempotent
  IF v_prev = 'completed' THEN
    RETURN;
  END IF;

  -- Validate transition
  PERFORM public.validate_ride_transition(v_prev, 'completed');

  -- Check remaining active bookings
  SELECT COUNT(*)::integer
    INTO v_remaining
    FROM public.bookings b
   WHERE b.ride_id = p_ride_id
     AND b.status IN ('confirmed', 'in_progress');

  -- Force-complete any remaining active bookings
  IF v_remaining > 0 THEN
    UPDATE public.bookings b
       SET status = 'completed'
     WHERE b.ride_id = p_ride_id
       AND b.status IN ('confirmed', 'in_progress');
  END IF;

  -- Complete the ride
  UPDATE public.rides SET status = 'completed' WHERE ride_id = p_ride_id;

  -- Close chat
  UPDATE public.chats c
     SET closed_at = timezone('utc', now())
   WHERE c.ride_id = p_ride_id
     AND c.closed_at IS NULL;

  -- History
  INSERT INTO public.ride_status_history (
    ride_id, status, previous_status, actor_id, reason
  )
  VALUES (
    p_ride_id, 'completed', v_prev, v_actor, 'manual_complete_by_driver'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_user_rating_on_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_avg numeric;
  v_is_driver boolean;
BEGIN
  -- Calculate new average for the reviewee
  SELECT AVG(r.rating)::numeric(3,2)
    INTO v_avg
    FROM public.ride_reviews r
   WHERE r.reviewee_id = NEW.reviewee_id;

  -- Update users.rating
  UPDATE public.users
     SET rating = v_avg,
         updated_at = now()
   WHERE uuid = NEW.reviewee_id;

  -- Check if reviewee is a driver, update driver_profiles.rating too
  SELECT EXISTS (
    SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = NEW.reviewee_id
  ) INTO v_is_driver;

  IF v_is_driver THEN
    UPDATE public.driver_profiles
       SET rating = v_avg
     WHERE user_id = NEW.reviewee_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_ride(p_ride_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_prev  text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  BEGIN
    SELECT r.status
      INTO STRICT v_prev
      FROM public.rides r
     WHERE r.ride_id = p_ride_id
       FOR UPDATE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE EXCEPTION 'El viaje no existe';
  END;

  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Solo el conductor puede iniciar el viaje';
  END IF;

  IF v_prev = 'in_progress' THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.bookings b
     WHERE b.ride_id = p_ride_id
       AND b.status = 'confirmed'
  ) THEN
    RAISE EXCEPTION 'Se requiere al menos una reserva confirmada';
  END IF;

  PERFORM public.validate_ride_transition(v_prev, 'in_progress');

  UPDATE public.rides SET status = 'in_progress' WHERE ride_id = p_ride_id;

  UPDATE public.bookings b
     SET status = 'rejected'
   WHERE b.ride_id = p_ride_id
     AND b.status = 'pending';

  INSERT INTO public.chats AS c (ride_id)
  VALUES (p_ride_id)
  ON CONFLICT (ride_id) DO NOTHING;

  INSERT INTO public.ride_status_history (
    ride_id,
    status,
    previous_status,
    actor_id,
    reason
  )
  VALUES (p_ride_id, 'in_progress', v_prev, v_actor, NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_stop(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor     uuid := auth.uid();
  v_booking   public.bookings%ROWTYPE;
  v_ride_id   uuid;
  v_prev_ride text;
  v_remain    integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_booking_id IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  SELECT b.*
    INTO v_booking
    FROM public.bookings b
   WHERE b.booking_id = p_booking_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La reserva no existe';
  END IF;

  v_ride_id := v_booking.ride_id;

  SELECT r.status
    INTO STRICT v_prev_ride
    FROM public.rides r
   WHERE r.ride_id = v_ride_id
     FOR UPDATE;

  SELECT b.*
    INTO v_booking
    FROM public.bookings b
   WHERE b.booking_id = p_booking_id
     FOR UPDATE;

  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = v_ride_id
       AND dp.user_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Solo el conductor puede completar paradas';
  END IF;

  IF v_booking.status = 'completed' THEN
    RETURN;
  END IF;

  IF v_booking.status NOT IN ('confirmed', 'in_progress') THEN
    RAISE EXCEPTION 'Estado de reserva invalido para esta accion';
  END IF;

  IF v_booking.status = 'confirmed' THEN
    PERFORM public.validate_booking_transition('confirmed', 'in_progress');
    UPDATE public.bookings b
       SET status = 'in_progress'
     WHERE b.booking_id = p_booking_id;

    SELECT b.*
      INTO v_booking
      FROM public.bookings b
     WHERE b.booking_id = p_booking_id;
  END IF;

  PERFORM public.validate_booking_transition(v_booking.status, 'completed');

  UPDATE public.bookings b
     SET status = 'completed'
   WHERE b.booking_id = p_booking_id;

  SELECT COUNT(*)::integer
    INTO v_remain
    FROM public.bookings b
   WHERE b.ride_id = v_ride_id
     AND b.status IN ('confirmed', 'in_progress');

  IF v_remain = 0 THEN
    PERFORM public.validate_ride_transition(v_prev_ride, 'completed');
    UPDATE public.rides SET status = 'completed' WHERE ride_id = v_ride_id;

    INSERT INTO public.ride_status_history (
      ride_id,
      status,
      previous_status,
      actor_id,
      reason
    )
    VALUES (
      v_ride_id,
      'completed',
      v_prev_ride,
      v_actor,
      NULL
    );

    UPDATE public.chats c
       SET closed_at = timezone('utc', now())
     WHERE c.ride_id = v_ride_id
       AND c.closed_at IS NULL;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_booking_transition(current_status text, new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NOT (
    (
      current_status = 'pending'
      AND new_status = ANY (
        ARRAY['confirmed', 'rejected', 'cancelled']::text[]
      )
    )
    OR (
      current_status = 'confirmed'
      AND new_status = ANY (
        ARRAY['in_progress', 'cancelled']::text[]
      )
    )
    OR (
      current_status = 'in_progress'
      AND new_status = ANY (
        ARRAY['completed', 'cancelled']::text[]
      )
    )
  ) THEN
    RAISE EXCEPTION 'Transición inválida de booking: % → %',
                  current_status,
                  new_status;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_ride_transition(current_status text, new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NOT (
    (
      current_status = 'scheduled'
      AND new_status = ANY (
        ARRAY['full', 'in_progress', 'cancelled']::text[]
      )
    )
    OR (
      current_status = 'full'
      AND new_status = ANY (
        ARRAY['scheduled', 'in_progress', 'cancelled']::text[]
      )
    )
    OR (
      current_status = 'in_progress'
      AND new_status = ANY (
        ARRAY['completed', 'cancelled']::text[]
      )
    )
  ) THEN
    RAISE EXCEPTION 'Transición inválida de ride: % → %',
                  current_status,
                  new_status;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_ride(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id     uuid;
  v_driver_id   uuid;
  v_vehicle_id  uuid;
  v_departure   timestamptz;
  v_seats       int;
  v_price       numeric;
  v_origin_lat  numeric;
  v_origin_lng  numeric;
  v_dest_lat    numeric;
  v_dest_lng    numeric;
  v_origin_addr text;
  v_dest_addr   text;
  v_polyline    text;
  v_ride_id     uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'No autenticado';
  end if;

  select driver_id into v_driver_id
  from public.driver_profiles
  where user_id = v_user_id
    and status  = 'approved'
  limit 1;

  if v_driver_id is null then
    raise exception 'El usuario no tiene perfil de conductor aprobado';
  end if;

  v_vehicle_id := (p_payload->>'vehicle_id')::uuid;
  v_departure  := (p_payload->>'departure_time')::timestamptz;
  v_seats      := (p_payload->>'available_seats')::int;
  v_price      := (p_payload->>'price_per_seat')::numeric;
  v_origin_lat := (p_payload->>'origin_lat')::numeric;
  v_origin_lng := (p_payload->>'origin_lng')::numeric;
  v_dest_lat   := (p_payload->>'destination_lat')::numeric;
  v_dest_lng   := (p_payload->>'destination_lng')::numeric;
  v_origin_addr := nullif(p_payload->>'origin_address', '');
  v_dest_addr   := nullif(p_payload->>'destination_address', '');
  v_polyline    := nullif(p_payload->>'route_polyline', '');

  if not exists (
    select 1 from public.vehicles
    where vehicle_id = v_vehicle_id
      and driver_id  = v_driver_id
      and is_active  = true
  ) then
    raise exception 'El vehiculo no existe o no pertenece al conductor';
  end if;

  if v_departure <= now() then
    raise exception 'La hora de salida debe ser en el futuro';
  end if;

  if v_seats < 1 then
    raise exception 'Debe haber al menos 1 asiento disponible al crear el viaje';
  end if;

  if v_price <= 0 then
    raise exception 'El precio por asiento debe ser mayor a 0';
  end if;

  insert into public.rides (
    driver_id,
    vehicle_id,
    origin_lat,
    origin_lng,
    destination_lat,
    destination_lng,
    origin_address,
    destination_address,
    route_polyline,
    departure_time,
    available_seats,
    price_per_seat
  )
  values (
    v_driver_id,
    v_vehicle_id,
    v_origin_lat,
    v_origin_lng,
    v_dest_lat,
    v_dest_lng,
    v_origin_addr,
    v_dest_addr,
    v_polyline,
    v_departure,
    v_seats,
    v_price
  )
  returning ride_id into v_ride_id;

  -- Origen (stop_order = 1) y destino (stop_order = 2) a nivel de ride.
  -- Las bookings de pasajeros referencian estos stops, en lugar de crear stops nuevos por reserva.
  insert into public.ride_stops (ride_id, lat, lng, address, stop_order)
  values (v_ride_id, v_origin_lat, v_origin_lng, coalesce(v_origin_addr, ''), 1);

  insert into public.ride_stops (ride_id, lat, lng, address, stop_order)
  values (v_ride_id, v_dest_lat, v_dest_lng, coalesce(v_dest_addr, ''), 2);

  insert into public.ride_status_history (ride_id, status)
  values (v_ride_id, 'scheduled');

  return v_ride_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_booking(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id        uuid;
  v_ride_id        uuid;
  v_seats          int;
  v_ride           rides%rowtype;
  v_pickup_stop    uuid;
  v_dropoff_stop   uuid;
  v_booking_id     uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'No autenticado';
  end if;

  v_ride_id := (p_payload->>'ride_id')::uuid;
  v_seats   := coalesce((p_payload->>'seats_reserved')::int, 1);

  if v_ride_id is null then
    raise exception 'ride_id es obligatorio';
  end if;
  if v_seats < 1 then
    raise exception 'Debe reservar al menos 1 asiento';
  end if;

  select * into v_ride from rides where ride_id = v_ride_id for update;
  if not found then
    raise exception 'El viaje no existe';
  end if;

  if v_ride.status <> 'scheduled' then
    raise exception 'El viaje ya no esta disponible para reserva';
  end if;
  if v_ride.departure_time <= now() then
    raise exception 'El viaje ya partio';
  end if;
  if v_ride.available_seats < v_seats then
    raise exception 'No hay suficientes asientos disponibles';
  end if;

  if exists (
    select 1 from driver_profiles dp
    where dp.driver_id = v_ride.driver_id
      and dp.user_id   = v_user_id
  ) then
    raise exception 'No puedes reservar tu propio viaje';
  end if;

  -- Verificar que el pasajero no tenga ya un booking activo en cualquier ride
  if exists (
    select 1 from bookings
    where user_id = auth.uid()
      and status = any(array['pending', 'confirmed', 'in_progress'])
  ) then
    raise exception 'Ya tienes una reserva activa en otro viaje';
  end if;

  if exists (
    select 1 from bookings b
    where b.ride_id = v_ride_id
      and b.user_id = v_user_id
      and b.status in ('pending', 'confirmed')
  ) then
    raise exception 'Ya tienes una reserva activa para este viaje';
  end if;

  select stop_id into v_pickup_stop
  from ride_stops
  where ride_id = v_ride_id and stop_order = 1
  limit 1;

  select stop_id into v_dropoff_stop
  from ride_stops
  where ride_id = v_ride_id and stop_order = 2
  limit 1;

  if v_pickup_stop is null or v_dropoff_stop is null then
    raise exception 'El viaje no tiene paradas de origen y destino configuradas';
  end if;

  insert into bookings (
    ride_id, user_id, pickup_stop_id, dropoff_stop_id,
    seats_reserved, status
  ) values (
    v_ride_id, v_user_id, v_pickup_stop, v_dropoff_stop,
    v_seats, 'pending'
  )
  returning booking_id into v_booking_id;

  return v_booking_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_transport_stop(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_stop_id uuid := nullif(p_payload->>'stop_id', '')::uuid;
  v_external_id text := btrim(coalesce(p_payload->>'external_id', ''));
  v_name text := btrim(coalesce(p_payload->>'name', ''));
  v_address text := nullif(btrim(coalesce(p_payload->>'address', '')), '');
  v_municipality text := nullif(
    btrim(coalesce(p_payload->>'municipality', '')), ''
  );
  v_latitude double precision := (p_payload->>'latitude')::double precision;
  v_longitude double precision := (p_payload->>'longitude')::double precision;
  v_stop_type text := coalesce(p_payload->>'stop_type', 'general');
  v_active boolean := coalesce((p_payload->>'active')::boolean, true);
begin
  if not private.is_current_admin() then
    raise exception 'Acceso administrativo requerido';
  end if;
  if v_external_id = '' or v_name = '' then
    raise exception 'External ID y nombre son requeridos';
  end if;
  if v_latitude not between -90 and 90
     or v_longitude not between -180 and 180 then
    raise exception 'Coordenadas no validas';
  end if;
  if v_stop_type not in ('general', 'official_boarding_zone') then
    raise exception 'Tipo de parada no valido';
  end if;

  if v_stop_id is null then
    insert into public.transport_stops (
      external_id, name, address, municipality,
      latitude, longitude, source, active, stop_type
    ) values (
      v_external_id, v_name, v_address, v_municipality,
      v_latitude, v_longitude, 'krow_admin', v_active, v_stop_type
    )
    returning stop_id into v_stop_id;
  else
    update public.transport_stops
    set external_id = v_external_id,
        name = v_name,
        address = v_address,
        municipality = v_municipality,
        latitude = v_latitude,
        longitude = v_longitude,
        active = v_active,
        stop_type = v_stop_type,
        updated_at = now()
    where stop_id = v_stop_id;
    if not found then raise exception 'Parada no encontrada'; end if;
  end if;
  return v_stop_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_review(p_ride_id uuid, p_reviewee_id uuid, p_rating smallint, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_ride_status text;
  v_review_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_ride_id IS NULL OR p_reviewee_id IS NULL OR p_rating IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  IF p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'La calificacion debe estar entre 1 y 5';
  END IF;

  IF v_actor = p_reviewee_id THEN
    RAISE EXCEPTION 'No puedes calificarte a ti mismo';
  END IF;

  -- Verify ride is completed
  SELECT r.status INTO v_ride_status
    FROM public.rides r
   WHERE r.ride_id = p_ride_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El viaje no existe';
  END IF;

  IF v_ride_status <> 'completed' THEN
    RAISE EXCEPTION 'Solo se pueden calificar viajes completados';
  END IF;

  -- Verify reviewer participated in the ride (as driver or passenger with completed booking)
  IF NOT EXISTS (
    -- Is the driver of this ride
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = v_actor
  ) AND NOT EXISTS (
    -- Has a completed booking on this ride
    SELECT 1
      FROM public.bookings b
     WHERE b.ride_id = p_ride_id
       AND b.user_id = v_actor
       AND b.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'No participaste en este viaje';
  END IF;

  -- Verify reviewee participated in the ride
  IF NOT EXISTS (
    SELECT 1
      FROM public.driver_profiles dp
      JOIN public.rides rr ON rr.driver_id = dp.driver_id
     WHERE rr.ride_id = p_ride_id
       AND dp.user_id = p_reviewee_id
  ) AND NOT EXISTS (
    SELECT 1
      FROM public.bookings b
     WHERE b.ride_id = p_ride_id
       AND b.user_id = p_reviewee_id
       AND b.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'La persona a calificar no participo en este viaje';
  END IF;

  -- Upsert review
  INSERT INTO public.ride_reviews (
    ride_id, reviewer_id, reviewee_id, rating, comment
  ) VALUES (
    p_ride_id, v_actor, p_reviewee_id, p_rating, p_comment
  )
  ON CONFLICT (ride_id, reviewer_id, reviewee_id)
  DO UPDATE SET
    rating = EXCLUDED.rating,
    comment = EXCLUDED.comment,
    created_at = now()
  RETURNING review_id INTO v_review_id;

  RETURN v_review_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.find_compatible_transport_stops(p_route_geojson jsonb, p_corridor_m integer DEFAULT 500)
 RETURNS TABLE(stop_id uuid, external_id text, name text, address text, municipality text, lat double precision, lng double precision, distance_from_route_m double precision, route_fraction double precision)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_route extensions.geometry;
begin
  if v_actor is null then raise exception 'No autenticado'; end if;
  if p_corridor_m < 1 or p_corridor_m > 5000 then
    raise exception 'El corredor solicitado no es valido';
  end if;
  v_route := extensions.st_setsrid(
    extensions.st_geomfromgeojson(p_route_geojson::text), 4326
  );
  if extensions.st_geometrytype(v_route) <> 'ST_LineString' then
    raise exception 'La geometria de ruta debe ser LineString';
  end if;
  return query
  select ts.stop_id, ts.external_id, ts.name, ts.address, ts.municipality,
    ts.latitude, ts.longitude,
    extensions.st_distance(ts.location, v_route::extensions.geography),
    extensions.st_linelocatepoint(v_route, ts.location::extensions.geometry)
  from public.transport_stops ts
  where ts.active
    and extensions.st_dwithin(ts.location, v_route::extensions.geography, p_corridor_m)
  order by extensions.st_linelocatepoint(v_route, ts.location::extensions.geometry), ts.name;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_favorite_route(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_driver_id uuid;
  v_route_id uuid;
  v_stop_ids uuid[];
  v_selected_count integer;
  v_default_vehicle_id uuid;
  v_default_capacity integer;
  v_default_seats integer;
  v_default_price numeric;
  v_route_name text;
begin
  if v_actor is null then raise exception 'No autenticado'; end if;
  select dp.driver_id into v_driver_id
  from public.driver_profiles dp
  where dp.user_id = v_actor and dp.status = 'approved';
  if v_driver_id is null then
    raise exception 'Se requiere un perfil de conductor aprobado';
  end if;

  v_route_name := btrim(coalesce(p_payload->>'name', ''));
  if length(v_route_name) < 1 or length(v_route_name) > 80 then
    raise exception 'El nombre de la ruta no es valido';
  end if;
  select coalesce(array_agg(item.value::uuid order by item.ordinality), '{}'::uuid[])
    into v_stop_ids
  from jsonb_array_elements_text(
    coalesce(p_payload->'transport_stop_ids', '[]'::jsonb)
  ) with ordinality as item(value, ordinality);
  if cardinality(v_stop_ids) < 2 then
    raise exception 'Selecciona al menos dos paradas';
  end if;
  if cardinality(v_stop_ids) <> (
    select count(distinct selected_id) from unnest(v_stop_ids) as selected_id
  ) then
    raise exception 'Las paradas no pueden repetirse';
  end if;
  select count(*) into v_selected_count
  from private.route_stop_selection(p_payload->'route_geojson', v_stop_ids, 500);
  if v_selected_count <> cardinality(v_stop_ids) then
    raise exception 'Una o mas paradas no pertenecen al corredor de la ruta';
  end if;

  v_default_vehicle_id := nullif(p_payload->>'default_vehicle_id', '')::uuid;
  v_default_seats := nullif(p_payload->>'default_available_seats', '')::integer;
  v_default_price := nullif(p_payload->>'default_price_per_seat', '')::numeric;
  if v_default_vehicle_id is not null then
    select v.capacity into v_default_capacity
    from public.vehicles v
    where v.vehicle_id = v_default_vehicle_id
      and v.driver_id = v_driver_id and v.is_active;
    if v_default_capacity is null then
      raise exception 'El vehiculo predeterminado no es valido';
    end if;
    if v_default_seats is not null
       and v_default_seats > greatest(v_default_capacity - 1, 0) then
      raise exception 'Los asientos exceden la capacidad del vehiculo';
    end if;
  end if;
  if v_default_seats is not null and v_default_seats < 1 then
    raise exception 'La cantidad predeterminada de asientos no es valida';
  end if;
  if v_default_price is not null and v_default_price <= 0 then
    raise exception 'El precio predeterminado debe ser mayor que cero';
  end if;

  v_route_id := nullif(p_payload->>'route_id', '')::uuid;
  if v_route_id is null then
    insert into public.favorite_routes (
      driver_id, name, origin_place_id, origin_address, origin_lat, origin_lng,
      destination_place_id, destination_address, destination_lat, destination_lng,
      default_vehicle_id, default_available_seats, default_price_per_seat
    ) values (
      v_driver_id, v_route_name,
      nullif(p_payload->>'origin_place_id', ''), p_payload->>'origin_address',
      (p_payload->>'origin_lat')::double precision,
      (p_payload->>'origin_lng')::double precision,
      nullif(p_payload->>'destination_place_id', ''), p_payload->>'destination_address',
      (p_payload->>'destination_lat')::double precision,
      (p_payload->>'destination_lng')::double precision,
      v_default_vehicle_id, v_default_seats, v_default_price
    ) returning route_id into v_route_id;
  else
    perform 1 from public.favorite_routes fr
    where fr.route_id = v_route_id and fr.driver_id = v_driver_id for update;
    if not found then raise exception 'Ruta favorita no encontrada'; end if;
    update public.favorite_routes
    set name = v_route_name,
        origin_place_id = nullif(p_payload->>'origin_place_id', ''),
        origin_address = p_payload->>'origin_address',
        origin_lat = (p_payload->>'origin_lat')::double precision,
        origin_lng = (p_payload->>'origin_lng')::double precision,
        destination_place_id = nullif(p_payload->>'destination_place_id', ''),
        destination_address = p_payload->>'destination_address',
        destination_lat = (p_payload->>'destination_lat')::double precision,
        destination_lng = (p_payload->>'destination_lng')::double precision,
        default_vehicle_id = v_default_vehicle_id,
        default_available_seats = v_default_seats,
        default_price_per_seat = v_default_price,
        updated_at = now()
    where route_id = v_route_id;
    delete from public.favorite_route_stops where route_id = v_route_id;
  end if;
  insert into public.favorite_route_stops (
    route_id, transport_stop_id, stop_order, route_fraction
  )
  select v_route_id, selection.stop_id, selection.stop_order, selection.route_fraction
  from private.route_stop_selection(
    p_payload->'route_geojson', v_stop_ids, 500
  ) selection;
  return v_route_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_ride_v2(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_driver_id uuid;
  v_vehicle_id uuid;
  v_vehicle_capacity integer;
  v_favorite_route_id uuid;
  v_ride_id uuid;
  v_stop_ids uuid[];
  v_selected_count integer;
  v_available_seats integer;
  v_price numeric;
  v_departure timestamptz;
begin
  if v_actor is null then raise exception 'No autenticado'; end if;
  select dp.driver_id into v_driver_id
  from public.driver_profiles dp
  where dp.user_id = v_actor and dp.status = 'approved';
  if v_driver_id is null then
    raise exception 'Se requiere un perfil de conductor aprobado';
  end if;
  v_vehicle_id := (p_payload->>'vehicle_id')::uuid;
  select v.capacity into v_vehicle_capacity
  from public.vehicles v
  where v.vehicle_id = v_vehicle_id
    and v.driver_id = v_driver_id and v.is_active;
  if v_vehicle_capacity is null then raise exception 'Vehiculo no valido'; end if;
  v_available_seats := (p_payload->>'available_seats')::integer;
  if v_available_seats < 1
     or v_available_seats > greatest(v_vehicle_capacity - 1, 0) then
    raise exception 'Los asientos exceden la capacidad disponible';
  end if;
  v_price := (p_payload->>'price_per_seat')::numeric;
  if v_price <= 0 then raise exception 'El precio debe ser mayor que cero'; end if;
  v_departure := (p_payload->>'departure_time')::timestamptz;
  if v_departure < now() + interval '15 minutes' then
    raise exception 'La salida debe programarse con al menos 15 minutos';
  end if;

  v_favorite_route_id := nullif(p_payload->>'favorite_route_id', '')::uuid;
  if v_favorite_route_id is not null and not exists (
    select 1 from public.favorite_routes fr
    where fr.route_id = v_favorite_route_id and fr.driver_id = v_driver_id
  ) then
    raise exception 'Ruta favorita no valida';
  end if;
  select coalesce(array_agg(item.value::uuid order by item.ordinality), '{}'::uuid[])
    into v_stop_ids
  from jsonb_array_elements_text(
    coalesce(p_payload->'transport_stop_ids', '[]'::jsonb)
  ) with ordinality as item(value, ordinality);
  if cardinality(v_stop_ids) < 2 then raise exception 'Selecciona al menos dos paradas'; end if;
  if cardinality(v_stop_ids) <> (
    select count(distinct selected_id) from unnest(v_stop_ids) as selected_id
  ) then raise exception 'Las paradas no pueden repetirse'; end if;
  select count(*) into v_selected_count
  from private.route_stop_selection(p_payload->'route_geojson', v_stop_ids, 500);
  if v_selected_count <> cardinality(v_stop_ids) then
    raise exception 'Una o mas paradas no pertenecen al corredor de la ruta';
  end if;

  insert into public.rides (
    driver_id, vehicle_id, favorite_route_id,
    origin_lat, origin_lng, destination_lat, destination_lng,
    origin_address, destination_address, route_polyline,
    route_distance_meters, route_duration_seconds, route_provider,
    route_calculated_at, departure_time, available_seats,
    price_per_seat, status
  ) values (
    v_driver_id, v_vehicle_id, v_favorite_route_id,
    (p_payload->>'origin_lat')::numeric, (p_payload->>'origin_lng')::numeric,
    (p_payload->>'destination_lat')::numeric,
    (p_payload->>'destination_lng')::numeric,
    nullif(p_payload->>'origin_address', ''),
    nullif(p_payload->>'destination_address', ''),
    p_payload->>'route_polyline',
    (p_payload->>'route_distance_meters')::integer,
    (p_payload->>'route_duration_seconds')::integer,
    coalesce(nullif(p_payload->>'route_provider', ''), 'google'),
    coalesce((p_payload->>'route_calculated_at')::timestamptz, now()),
    v_departure, v_available_seats, v_price, 'scheduled'
  ) returning ride_id into v_ride_id;
  insert into public.ride_stops (
    ride_id, transport_stop_id, lat, lng, address,
    stop_order, route_version, is_active, route_fraction
  )
  select v_ride_id, ts.stop_id, ts.latitude, ts.longitude,
    coalesce(nullif(ts.address, ''), ts.name),
    selection.stop_order, 1, true, selection.route_fraction
  from private.route_stop_selection(
    p_payload->'route_geojson', v_stop_ids, 500
  ) selection
  join public.transport_stops ts on ts.stop_id = selection.stop_id;
  insert into public.ride_status_history (
    ride_id, status, previous_status, actor_id, reason
  ) values (
    v_ride_id, 'scheduled', null, v_actor, 'ride_created_with_catalog_stops'
  );
  return v_ride_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_ride_v2(p_ride_id uuid, p_expected_version integer, p_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_driver_id uuid;
  v_ride public.rides%rowtype;
  v_vehicle_id uuid;
  v_vehicle_capacity integer;
  v_favorite_route_id uuid;
  v_stop_ids uuid[];
  v_selected_count integer;
  v_available_seats integer;
  v_price numeric;
  v_departure timestamptz;
  v_new_version integer;
begin
  if v_actor is null then raise exception 'No autenticado'; end if;
  select dp.driver_id into v_driver_id
  from public.driver_profiles dp
  where dp.user_id = v_actor and dp.status = 'approved';
  if v_driver_id is null then
    raise exception 'Se requiere un perfil de conductor aprobado';
  end if;
  select * into v_ride from public.rides r
  where r.ride_id = p_ride_id for update;
  if not found or v_ride.driver_id <> v_driver_id then
    raise exception 'Viaje no encontrado';
  end if;
  if v_ride.status <> 'scheduled' then
    raise exception 'El viaje ya no se puede editar';
  end if;
  if v_ride.version <> p_expected_version then
    raise exception 'Conflicto de version del viaje';
  end if;
  if exists (
    select 1 from public.bookings b
    where b.ride_id = p_ride_id
      and b.status in ('pending', 'confirmed', 'in_progress')
  ) then
    raise exception 'El viaje tiene reservas activas y no se puede editar';
  end if;

  v_vehicle_id := (p_payload->>'vehicle_id')::uuid;
  select v.capacity into v_vehicle_capacity
  from public.vehicles v
  where v.vehicle_id = v_vehicle_id
    and v.driver_id = v_driver_id and v.is_active;
  if v_vehicle_capacity is null then raise exception 'Vehiculo no valido'; end if;
  v_available_seats := (p_payload->>'available_seats')::integer;
  if v_available_seats < 1
     or v_available_seats > greatest(v_vehicle_capacity - 1, 0) then
    raise exception 'Los asientos exceden la capacidad disponible';
  end if;
  v_price := (p_payload->>'price_per_seat')::numeric;
  if v_price <= 0 then raise exception 'El precio debe ser mayor que cero'; end if;
  v_departure := (p_payload->>'departure_time')::timestamptz;
  if v_departure < now() + interval '15 minutes' then
    raise exception 'La salida debe programarse con al menos 15 minutos';
  end if;
  v_favorite_route_id := nullif(p_payload->>'favorite_route_id', '')::uuid;
  if v_favorite_route_id is not null and not exists (
    select 1 from public.favorite_routes fr
    where fr.route_id = v_favorite_route_id and fr.driver_id = v_driver_id
  ) then
    raise exception 'Ruta favorita no valida';
  end if;

  select coalesce(array_agg(item.value::uuid order by item.ordinality), '{}'::uuid[])
    into v_stop_ids
  from jsonb_array_elements_text(
    coalesce(p_payload->'transport_stop_ids', '[]'::jsonb)
  ) with ordinality as item(value, ordinality);
  if cardinality(v_stop_ids) < 2 then raise exception 'Selecciona al menos dos paradas'; end if;
  if cardinality(v_stop_ids) <> (
    select count(distinct selected_id) from unnest(v_stop_ids) as selected_id
  ) then raise exception 'Las paradas no pueden repetirse'; end if;
  select count(*) into v_selected_count
  from private.route_stop_selection(p_payload->'route_geojson', v_stop_ids, 500);
  if v_selected_count <> cardinality(v_stop_ids) then
    raise exception 'Una o mas paradas no pertenecen al corredor de la ruta';
  end if;

  v_new_version := v_ride.version + 1;
  update public.ride_stops set is_active = false
  where ride_id = p_ride_id and is_active;
  update public.rides
  set vehicle_id = v_vehicle_id,
      favorite_route_id = v_favorite_route_id,
      origin_lat = (p_payload->>'origin_lat')::numeric,
      origin_lng = (p_payload->>'origin_lng')::numeric,
      destination_lat = (p_payload->>'destination_lat')::numeric,
      destination_lng = (p_payload->>'destination_lng')::numeric,
      origin_address = nullif(p_payload->>'origin_address', ''),
      destination_address = nullif(p_payload->>'destination_address', ''),
      route_polyline = p_payload->>'route_polyline',
      route_distance_meters = (p_payload->>'route_distance_meters')::integer,
      route_duration_seconds = (p_payload->>'route_duration_seconds')::integer,
      route_provider = coalesce(nullif(p_payload->>'route_provider', ''), 'google'),
      route_calculated_at = coalesce(
        (p_payload->>'route_calculated_at')::timestamptz, now()
      ),
      departure_time = v_departure,
      available_seats = v_available_seats,
      price_per_seat = v_price,
      updated_at = now(),
      version = v_new_version
  where ride_id = p_ride_id;
  insert into public.ride_stops (
    ride_id, transport_stop_id, lat, lng, address,
    stop_order, route_version, is_active, route_fraction
  )
  select p_ride_id, ts.stop_id, ts.latitude, ts.longitude,
    coalesce(nullif(ts.address, ''), ts.name),
    selection.stop_order, v_new_version, true, selection.route_fraction
  from private.route_stop_selection(
    p_payload->'route_geojson', v_stop_ids, 500
  ) selection
  join public.transport_stops ts on ts.stop_id = selection.stop_id;
  insert into public.ride_status_history (
    ride_id, status, previous_status, actor_id, reason
  ) values (
    p_ride_id, 'scheduled', 'scheduled', v_actor, 'ride_updated_by_driver'
  );
  return v_new_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_booking_v2(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_ride public.rides%rowtype;
  v_booking_id uuid;
  v_pickup public.ride_stops%rowtype;
  v_dropoff public.ride_stops%rowtype;
  v_seats integer;
begin
  if v_actor is null then raise exception 'No autenticado'; end if;
  if not exists (select 1 from public.users u where u.uuid = v_actor) then
    raise exception 'Perfil de usuario no encontrado';
  end if;
  select * into v_ride
  from public.rides r
  where r.ride_id = (p_payload->>'ride_id')::uuid
  for update;
  if not found then raise exception 'El viaje no existe'; end if;
  if v_ride.status <> 'scheduled' then
    raise exception 'El viaje no acepta reservaciones';
  end if;
  if exists (
    select 1 from public.driver_profiles dp
    where dp.driver_id = v_ride.driver_id and dp.user_id = v_actor
  ) then
    raise exception 'No puedes reservar tu propio viaje';
  end if;
  if exists (
    select 1 from public.bookings b
    where b.user_id = v_actor
      and b.status in ('pending', 'confirmed', 'in_progress')
  ) then
    raise exception 'Ya tienes una reservacion activa';
  end if;
  v_seats := coalesce((p_payload->>'seats_reserved')::integer, 1);
  if v_seats < 1 or v_seats > v_ride.available_seats then
    raise exception 'No hay suficientes asientos disponibles';
  end if;
  select * into v_pickup from public.ride_stops rs
  where rs.stop_id = (p_payload->>'pickup_stop_id')::uuid
    and rs.ride_id = v_ride.ride_id and rs.is_active
    and rs.route_version = v_ride.version;
  select * into v_dropoff from public.ride_stops rs
  where rs.stop_id = (p_payload->>'dropoff_stop_id')::uuid
    and rs.ride_id = v_ride.ride_id and rs.is_active
    and rs.route_version = v_ride.version;
  if v_pickup.stop_id is null or v_dropoff.stop_id is null then
    raise exception 'Las paradas seleccionadas no son validas';
  end if;
  if v_pickup.transport_stop_id is null
     or v_dropoff.transport_stop_id is null
     or v_pickup.stop_order >= v_dropoff.stop_order then
    raise exception 'La parada de bajada debe estar despues de la subida';
  end if;
  insert into public.bookings (
    ride_id, user_id, pickup_stop_id, dropoff_stop_id,
    seats_reserved, status
  ) values (
    v_ride.ride_id, v_actor, v_pickup.stop_id, v_dropoff.stop_id,
    v_seats, 'pending'
  ) returning booking_id into v_booking_id;
  return v_booking_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_booking_status(p_booking_id uuid, p_new_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor     uuid := auth.uid();
  v_booking   public.bookings%ROWTYPE;
  v_ride      public.rides%ROWTYPE;
  v_prev_ride text;
  v_is_driver boolean;
  v_is_owner  boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  IF p_booking_id IS NULL OR p_new_status IS NULL THEN
    RAISE EXCEPTION 'Argumentos invalidos';
  END IF;

  SELECT *
    INTO v_booking
    FROM public.bookings b
   WHERE b.booking_id = p_booking_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La reserva no existe';
  END IF;

  SELECT *
    INTO v_ride
    FROM public.rides r
   WHERE r.ride_id = v_booking.ride_id
     FOR UPDATE;

  SELECT *
    INTO v_booking
    FROM public.bookings b
   WHERE b.booking_id = p_booking_id
     FOR UPDATE;

  IF v_booking.status = p_new_status THEN
    RETURN;
  END IF;

  v_prev_ride := v_ride.status;

  SELECT EXISTS (
           SELECT 1
             FROM public.driver_profiles dp
            WHERE dp.driver_id = v_ride.driver_id
              AND dp.user_id = v_actor
         )
    INTO v_is_driver;

  v_is_owner := v_booking.user_id = v_actor;

  IF NOT (v_is_driver OR v_is_owner) THEN
    RAISE EXCEPTION 'No tienes permiso para modificar esta reserva';
  END IF;

  IF v_is_driver THEN
    IF p_new_status NOT IN ('confirmed', 'rejected') THEN
      RAISE EXCEPTION 'Estado no permitido para el conductor';
    END IF;
  ELSIF p_new_status <> 'cancelled' THEN
    RAISE EXCEPTION 'Solo el pasajero puede cancelar desde el cliente';
  END IF;

  PERFORM public.validate_booking_transition(v_booking.status, p_new_status);

  IF p_new_status = 'confirmed' THEN
    IF v_booking.status <> 'pending' THEN
      RAISE EXCEPTION 'Solo se pueden confirmar reservas pendientes';
    END IF;

    IF v_ride.available_seats < v_booking.seats_reserved THEN
      RAISE EXCEPTION 'Ya no hay suficientes asientos disponibles';
    END IF;

    UPDATE public.bookings b
       SET status = 'confirmed'
     WHERE b.booking_id = p_booking_id;

    UPDATE public.rides r
       SET available_seats = r.available_seats - v_booking.seats_reserved
     WHERE r.ride_id = v_booking.ride_id
    RETURNING * INTO v_ride;

    IF v_ride.available_seats = 0 THEN
      IF v_prev_ride IS DISTINCT FROM 'full' THEN
        PERFORM public.validate_ride_transition(v_prev_ride, 'full');
        UPDATE public.rides r SET status = 'full' WHERE r.ride_id = v_booking.ride_id;
        INSERT INTO public.ride_status_history (
          ride_id,
          status,
          previous_status,
          actor_id,
          reason
        )
        VALUES (
          v_booking.ride_id,
          'full',
          v_prev_ride,
          v_actor,
          p_reason
        );
      END IF;
    END IF;

    RETURN;
  END IF;

  IF p_new_status = 'rejected' THEN
    UPDATE public.bookings b
       SET status = 'rejected'
     WHERE b.booking_id = p_booking_id;
    RETURN;
  END IF;

  IF p_new_status = 'cancelled' THEN
    IF v_booking.status = 'confirmed' THEN
      UPDATE public.rides r
         SET available_seats = r.available_seats + v_booking.seats_reserved
       WHERE r.ride_id = v_booking.ride_id;

      IF v_prev_ride = 'full' THEN
        PERFORM public.validate_ride_transition('full', 'scheduled');
        UPDATE public.rides r
           SET status = 'scheduled'
         WHERE r.ride_id = v_booking.ride_id;
        INSERT INTO public.ride_status_history (
          ride_id,
          status,
          previous_status,
          actor_id,
          reason
        )
        VALUES (
          v_booking.ride_id,
          'scheduled',
          'full',
          v_actor,
          p_reason
        );
      END IF;
    END IF;

    UPDATE public.bookings b
       SET status = 'cancelled'
     WHERE b.booking_id = p_booking_id;
    RETURN;
  END IF;

  RAISE EXCEPTION 'Estado de destino no soportado';
END;
$function$
